"""Whole augmented header: tags, callbacks, insertion and all erase cases."""
def register(topic, q, detail):
    def lesson(title, symbol, why, principle, use, reading, qa, cards):
        topic(title, '라이브러리·알고리즘', 'include/linux/rbtree_augmented.h', symbol,
              why, principle, use, reading, *(q(*x) for x in qa),
              details=[detail(*x) for x in cards])

    lesson('레드블랙 비트 표식·부모 갱신과 색 보존', 'rb_set_parent',
        '부모 주소와 색이 결합된 저장 표현을 안전하게 분리하고 갱신하는 방법을 배웁니다.',
        'RB_RED는 0, RB_BLACK은 1입니다. __rb_parent는 낮은 두 비트를 제거하고 __rb_color는 낮은 색 비트를 선택합니다. rb_set_parent는 이전 색을 유지하며 새 부모 주소를 결합합니다. rb_set_parent_color는 새 부모와 지정 색을 함께 저장합니다. 주소 정렬로 낮은 비트를 확보하는 표현의 전제와 연결됩니다.',
        '회전으로 부모만 바꾸는 경우와 색까지 바꾸는 경우에 맞는 helper를 선택합니다. 포인터 산술이 아니라 주소와 태그의 결합입니다. 정렬되지 않은 임의 주소나 다른 색 숫자를 넣는 일반 저장 함수로 쓰지 않습니다.',
        '__rb_parent·__rb_color 매크로와 두 setter를 비교하세요.',
        [('rb_set_parent가 유지하는 정보는?', '기존 노드의 색이다', '기존 부모 주소를 무조건 유지한다', '새 부모 주소에 rb_color(rb)를 더합니다. 이름처럼 부모는 바뀌고 기존 색이 유지됩니다.'),
         ('__rb_parent에서 낮은 비트를 제거하는 이유는?', '부모 주소에 결합된 색·예약 비트를 제외하기 위해서다', '부모의 키를 절반으로 나누기 위해서다', '부모·색 표현의 낮은 비트는 주소 자체가 아닙니다. ~3 마스크로 그 부분을 제외하고 부모 포인터를 복원합니다.')],
        [('색 검사', 'rb_is_red와 rb_is_black은 노드 포인터를 역참조합니다. NULL 잎이 검정이라는 트리 규칙이 NULL을 그대로 이 매크로에 넘겨도 된다는 뜻은 아닙니다.'),
         ('내부 계약', '헤더 앞 주석은 공개 콜백 구조와 삽입·삭제 API 외의 구현 세부 사항에 직접 의존하지 말라고 설명합니다. 공부용 내부 추적과 호출 코드의 API 선택을 구분합니다.')])

    lesson('레드블랙 상위 연결·부모 자식 또는 전체 루트 갱신', '__rb_change_child',
        '같은 연결 변경을 일반 부모와 루트에서 어떻게 처리하는지 배웁니다.',
        '부모가 있으면 old가 왼쪽 자식인지 확인해 해당 자식 포인터를 new로 바꿉니다. 아니면 오른쪽 자식을 바꿉니다. 부모가 없으면 전체 root->rb_node를 바꿉니다. 일반 함수는 WRITE_ONCE를 사용하고 RCU 형태는 rcu_assign_pointer를 사용해 공개 순서를 연결합니다.',
        'old가 실제 그 부모의 자식이라는 호출 전제를 지킵니다. old를 검색하거나 부모 관계가 맞는지 오류로 반환하는 함수가 아닙니다. new가 NULL인 삭제와 non-NULL인 회전·교체를 함께 추적합니다.',
        'parent 유무와 parent->rb_left==old의 두 분기를 읽으세요.',
        [('부모가 있지만 old가 실제 자식이 아니라면?', '내부 전제를 위반하며 이 함수가 안전한 오류를 반환하지 않는다', '전체 트리를 검색해 올바른 부모를 찾아준다', '왼쪽이 아니면 오른쪽을 갱신합니다. 유효한 연결 변경 호출을 전제로 하므로 잘못된 old·parent 관계를 검사하는 공개 검색 함수가 아닙니다.'),
         ('RCU 형태에서 상위 공개에 쓰는 것은?', 'rcu_assign_pointer다', '사용자 공간 파일 쓰기 함수다', '자식 또는 루트 공개를 RCU 포인터 대입으로 수행합니다. 이 공개만으로 writer 직렬화나 지연 해제가 완성되지는 않습니다.')],
        [('NULL 대체', '삭제로 자식이 사라지는 경우 new는 NULL일 수 있습니다. 상위 연결이 NULL을 가리키도록 바꾸며 새 객체를 할당하지 않습니다.'),
         ('순서 책임', 'RCU 대체는 후속 객체 초기화 후 공개해야 합니다. 이 helper 이전에 어떤 연결과 자료를 준비했는지 호출 위치에서 확인합니다.')])

    lesson('확장 트리 콜백·전파·복사·회전의 세 역할', 'RB_DECLARE_CALLBACKS',
        '부분 트리 요약값을 연결 변화에 맞게 유지하는 세 종류의 콜백을 배웁니다.',
        'propagate는 node에서 stop 직전까지 부모 방향으로 재계산하고 RBCOMPUTE(node,true)가 변화 없음으로 참을 반환하면 멈춥니다. copy는 대체 노드에 이전 부분 트리 요약을 복사합니다. rotate는 올라간 new에 old 요약을 넘긴 뒤 내려간 old를 RBCOMPUTE(old,false)로 다시 계산합니다. 매크로는 이름 결합으로 세 함수와 콜백 표를 생성합니다.',
        '각 노드의 자료, 자식의 요약과 stop 경계를 바탕으로 RBCOMPUTE를 작성합니다. 참 반환은 오류가 아니라 상위 전파를 중단해도 되는 변화 없음 의미입니다. 회전 전후의 전체 부분 트리와 내려간 작은 부분 트리를 구분합니다.',
        '## 이름 결합과 compute의 true·false 인자를 읽으세요.',
        [('propagate의 compute가 참을 반환하는 의미는?', '상위 전파를 멈춰도 되는 변화 없음이다', '항상 메모리 할당 실패다', '매크로는 참이면 break합니다. 호출자가 구현하는 compute는 이 중단 의미를 지켜야 하며 오류 코드와 구분합니다.'),
         ('rotate에서 new가 먼저 이어받는 것은?', '회전 전 old의 전체 부분 트리 요약이다', '임의의 인접 노드 주소다', 'new가 올라간 전체 부분 트리는 이전 old의 범위와 같습니다. 내려간 old의 부분 트리는 달라져 따로 재계산합니다.')],
        [('stop 제외', '전파는 rb!=stop인 동안 실행합니다. stop 자체를 갱신해야 하는지 다른 단계가 맡는지 삭제 호출 흐름과 함께 확인합니다.'),
         ('초기 상태', '새 노드의 자체 요약이 준비되어 있어야 합니다. 불필요한 전파를 줄이는 early exit는 자식과 기존 요약이 일관된다는 조건에 의존합니다.')])

    lesson('확장 최대값 콜백·자체 값과 두 자식 요약 합치기', 'RB_DECLARE_CALLBACKS_MAX',
        '부분 트리 최대값을 자동 생성하는 요약 함수와 가지치기의 전제를 배웁니다.',
        'compute_max는 RBCOMPUTE(node)의 자체 값에서 시작합니다. 왼쪽·오른쪽 자식이 있으면 각 자식의 저장 요약과 비교해 최댓값을 구합니다. exit가 참이고 이전 값과 같으면 참을 반환해 전파를 멈춥니다. 아니면 요약을 저장하고 거짓을 반환합니다. 이 함수를 일반 RB_DECLARE_CALLBACKS와 연결해 세 콜백을 생성합니다.',
        '구간 트리의 부분 트리 끝점 최대값처럼 모든 자식에 대한 동일 요약 규칙을 사용합니다. 자식 요약이 오래되면 부모 최대값도 잘못되므로 삭제·회전·값 변경 후 전파를 빠뜨리지 않습니다. 최소값이나 합계가 필요하면 다른 compute 계약을 작성합니다.',
        '두 자식의 RBAUGMENTED와 exit 비교를 읽으세요.',
        [('자체 값 5, 왼쪽 요약 12, 오른쪽 요약 9이면?', '부분 트리 최대값은 12다', '자체 값 5만 저장한다', '요약은 노드 하나가 아닌 전체 부분 트리를 대표합니다. 자체 값과 두 자식 요약의 최댓값을 저장합니다.'),
         ('자식 요약이 잘못된 상태에서 부모만 재계산하면?', '올바른 부분 트리 최대값을 보장할 수 없다', '항상 모든 후손을 직접 검색해 고쳐 준다', 'compute_max는 자식의 저장 요약을 사용합니다. 후손을 모두 순회하지 않으므로 아래 요약이 먼저 유효해야 합니다.')],
        [('무변화 종료', '노드 요약이 바뀌지 않았다면 그 값에만 의존하는 상위 요약도 바뀌지 않을 수 있습니다. 이 규칙을 이용해 전파 비용을 줄입니다.'),
         ('구간 검색 연결', '끝점 최대값이 질의 시작보다 작으면 해당 부분 트리에 겹치는 구간이 없다고 가지치기할 수 있습니다. 잘못된 요약은 존재하는 결과를 놓치는 원인이 됩니다.')])

    lesson('확장 삽입·검색 경로 전파와 왼쪽 캐시', 'rb_add_augmented_cached',
        '삽입 위치 검색, 요약 전파, 색 복구와 최소 캐시를 하나의 흐름으로 연결하는 방법을 배웁니다.',
        'less를 따라 왼쪽 또는 오른쪽 빈 자식을 찾으며 오른쪽으로 이동하면 leftmost를 거짓으로 만듭니다. rb_link_node로 연결하고 parent에서 NULL까지 propagate를 수행합니다. rb_insert_augmented_cached는 새 최소이면 rb_leftmost를 바꾸고 사용자 회전 콜백으로 색 복구를 호출합니다. 반환은 새 최소인 경우 node이고 아니면 NULL입니다.',
        '새 노드의 요약값을 먼저 준비합니다. 낮은 수준 rb_insert_augmented를 직접 사용하는 경우 삽입 검색 경로의 요약 갱신을 호출자가 수행해야 합니다. helper 주석의 suboptimal은 parent 전파 방식의 비용 설명이며 잘못된 결과라는 뜻이 아닙니다.',
        'leftmost 변화, propagate(parent,NULL)와 cached 삽입 순서를 읽으세요.',
        [('새 삽입 helper의 NULL 반환은 삽입 실패인가?', '아니며 새 최소가 아니라는 뜻이다', '반드시 메모리 부족 오류다', 'rb_add_augmented_cached는 연결·복구 후 새 최소인 경우만 node를 반환합니다. NULL을 실패로 읽으면 실제 삽입된 노드를 놓칩니다.'),
         ('새 노드의 자체 요약은 언제 준비해야 하는가?', '부모 전파와 회전 전에 준비해야 한다', '정렬 검색이 끝난 뒤 임의로 지워도 된다', '부모 compute와 회전 콜백은 자식·노드의 요약에 의존합니다. 새 노드의 값과 요약이 유효해야 결과가 맞습니다.')],
        [('중복 키', 'less가 거짓인 동률은 오른쪽으로 삽입됩니다. 균형 회전 후 동률 노드가 항상 오른쪽에만 남는다는 가정을 검색 코드에 추가하지 않습니다.'),
         ('균형·캐시·요약', '색 복구, 최소 캐시와 부분 트리 요약은 서로 다른 상태입니다. 하나가 올바르다고 나머지도 자동으로 맞는다고 판단하지 않습니다.')])

    lesson('확장 삭제·자식 0개 또는 1개의 지역 처리', '__rb_erase_augmented',
        '후계자를 찾을 필요가 없는 삭제에서 연결과 색을 지역적으로 복구하는 방법을 배웁니다.',
        '왼쪽 자식이 없으면 오른쪽 자식으로 상위 연결을 대체합니다. 자식이 있으면 삭제 노드의 부모·색을 넘겨 검정으로 만들고 별도 색 복구를 생략합니다. 자식도 없으면 삭제된 색이 검정일 때만 부모를 rebalance로 반환합니다. 왼쪽 자식만 있으면 그 자식에 부모·색을 넘겨 대체합니다. 유효한 레드블랙에서 단일 자식은 빨강이어야 한다는 조건을 사용합니다.',
        '현재 트리의 유효한 연결 노드만 삭제합니다. 한 자식 사례의 색 전제가 왜 성립하는지 같은 검정 높이와 연속 빨강 금지를 이용해 확인합니다. 삭제 후 parent부터 요약 전파도 수행됩니다.',
        'if(!tmp), else if(!child)와 rebalance 설정을 읽으세요.',
        [('검정 노드의 유일한 자식이 유효한 레드블랙에서 가지는 색은?', '빨강이다', '반드시 검정이다', '반대쪽 NULL 잎과 같은 검정 높이를 유지하려면 유일한 자식이 검정 수를 추가할 수 없습니다. 연속 빨강 규칙과 함께 빨강 자식 조건이 나옵니다.'),
         ('빨간 잎을 지우면 검정 부족 복구가 필요한가?', '아니며 해당 경로의 검정 수는 바뀌지 않는다', '무조건 전체 루트 색 복구가 필요하다', '빨간 노드는 검정 높이에 포함되지 않습니다. 자식 없는 경우 원본은 검정 삭제일 때만 부모를 rebalance로 선택합니다.')],
        [('색 전달', '단일 빨강 자식은 검정 삭제 노드 자리에 올라가며 이전 검정 색을 받습니다. 경로의 검정 수가 보충되어 별도 복구가 필요 없습니다.'),
         ('빈 전체 트리', '유일한 루트 잎을 삭제하면 root는 NULL이 됩니다. 부모도 NULL이므로 부족분을 위로 복구할 대상이 없습니다.')])

    lesson('확장 삭제·오른쪽 후계자를 자리로 옮기기', '__rb_erase_augmented',
        '두 자식이 있는 노드를 지울 때 키 순서를 유지하는 후계자 대체와 요약 이동을 배웁니다.',
        '오른쪽 자식에 왼쪽 자식이 없으면 그 오른쪽 자식이 후계자입니다. 그렇지 않으면 오른쪽 부분 트리의 가장 왼쪽 노드를 찾고 그 오른쪽 자식을 원래 부모의 왼쪽에 연결합니다. 후계자를 삭제 위치로 옮겨 양쪽 자식을 연결하고 copy로 요약을 넘깁니다. 깊은 후계자 사례는 이전 부모부터 successor 직전까지 먼저 propagate합니다.',
        '후계자 객체의 내용물을 삭제 객체로 복사하는 방식이 아니라 실제 노드 연결을 옮기는 방식입니다. child2가 있으면 지역 검정 처리로 복구하고 없으면 후계자의 이전 색에 따라 rebalance를 선택합니다. 마지막에 삭제 노드의 부모·색을 후계자에 넘깁니다.',
        '오른쪽 직속 Case 2와 깊은 Case 3의 parent·child2·copy·propagate를 비교하세요.',
        [('오른쪽 부분 트리의 후계자는 어느 노드인가?', '그 부분 트리의 가장 왼쪽 노드다', '항상 가장 오른쪽 노드다', '현재보다 큰 원소 중 가장 작은 것이 다음 원소입니다. 오른쪽 부분 트리의 왼쪽 끝이 그 조건을 만족합니다.'),
         ('깊은 후계자를 옮길 때 이전 부모 경로를 전파하는 이유는?', '후계자가 빠진 부분 트리의 요약이 바뀌기 때문이다', '모든 키를 문자열로 바꾸기 위해서다', '원래 위치에서는 후계자가 제거되고 그 오른쪽 자식이 대체합니다. 삭제 자리의 요약뿐 아니라 원래 경로의 요약도 갱신해야 합니다.')],
        [('copy와 최종 전파', 'copy는 이전 전체 부분 트리의 요약을 전달하고 이후 propagate가 새 구조의 정확한 요약으로 보정합니다. copy를 전체 재계산이라고 생각하지 않습니다.'),
         ('복구 판단 순서', '후계자의 이전 색으로 원래 자리의 검정 부족을 판단한 뒤 삭제 자리의 부모·색을 덮어씁니다. 덮어쓴 뒤 색을 판단하면 제거된 경로의 상태를 잃습니다.')])

    lesson('확장 삭제 완료·전파와 색 복구·최소 캐시 갱신', 'rb_erase_augmented_cached',
        '연결 변경 후 요약·균형·왼쪽 캐시를 완성하는 전체 삭제 호출 흐름을 배웁니다.',
        '내부 삭제는 마지막 tmp에서 NULL까지 propagate하고 rebalance 부모를 반환합니다. rb_erase_augmented는 부모가 있으면 사용자 rotate 콜백을 넘겨 색 복구를 실행합니다. cached 형태는 삭제 노드가 rb_leftmost이면 먼저 rb_next(node)를 새 최소로 저장한 뒤 일반 확장 삭제를 수행합니다. 삭제 전 연결이 유지될 때 다음 노드를 구하는 순서가 중요합니다.',
        '기본 삭제와 확장 삭제를 자료의 요약 유무에 맞게 사용합니다. cached 삭제는 반환값으로 새 최소를 알려주는 기본 rb_erase_cached와 형식이 다르므로 같은 호출 계약이라고 가정하지 않습니다. 노드 해제와 빈 표식은 별도 책임입니다.',
        '최소 캐시 갱신이 실제 제거보다 앞에 놓이는지 읽으세요.',
        [('최소 노드 삭제 전에 rb_next를 구하는 이유는?', '원래 유효한 연결에서 다음 최소를 계산하기 위해서다', '삭제된 메모리를 해제한 뒤 읽기 위해서다', '순회는 부모와 자식 연결에 의존합니다. 제거와 해제 후가 아니라 유효한 기존 연결에서 다음 노드를 얻어 캐시를 갱신합니다.'),
         ('rb_erase_augmented의 rebalance 부모가 NULL이면?', '별도 색 복구를 호출하지 않는다', 'NULL 부모를 무조건 역참조해 복구한다', '지역 삭제 처리로 색이 맞거나 루트 경계에서 추가 복구가 필요 없을 수 있습니다. wrapper는 반환된 부모가 있을 때만 색 복구를 실행합니다.')],
        [('회전 후 요약', '색 복구 과정의 구조 회전도 요약 필드를 바꿉니다. 삭제 전파만 수행하고 이후 회전 콜백을 생략하면 확장 상태가 틀릴 수 있습니다.'),
         ('공개 경계', '헤더의 콜백 구조와 rb_insert_augmented·rb_erase_augmented가 공개 사용의 기준입니다. 내부 삭제 세부 함수를 임의로 조합하는 것과 계약에 맞는 wrapper 사용을 구분합니다.')])
